import React from 'react';

const getCategoryIcon = (category) => {
    const icons = { GPU: '🎮', CPU: '⚙️', SSD: '💾', RAM: '🧠' };
    return icons[category] || '📦';
};

const ProductCard = ({ product, onEdit, onDelete }) => {
    const isOutOfStock = product.stock === 0;
    const isLowStock = product.stock > 0 && product.stock <= 5;

    return (
        <div className={`product-card ${isOutOfStock ? 'out-of-stock' : ''}`}>
            <div className="product-card__header">
                <span className="badge category-badge">
                    {getCategoryIcon(product.category)} {product.category}
                </span>
                <span className="product-id">#{product.id.slice(0, 6)}</span>
            </div>
            
            <div className="product-card__content">
                <h3>{product.title}</h3>
                <p className="desc">{product.description}</p>
                
                <div className="price-row">
                    <span className="price">{product.price.toLocaleString()} ₽</span>
                    {isOutOfStock ? (
                        <span className="badge stock-danger">Нет в наличии</span>
                    ) : isLowStock ? (
                        <span className="badge stock-warning">Осталось {product.stock} шт.</span>
                    ) : (
                        <span className="badge stock-success">В наличии ({product.stock})</span>
                    )}
                </div>
            </div>

            <div className="product-card__actions">
                <button className="btn-edit" onClick={() => onEdit(product)}>✏️ Ред.</button>
                <button className="btn-delete" onClick={() => onDelete(product.id)}>🗑️</button>
            </div>
        </div>
    );
};

export default ProductCard;
